-- Campaign hub, part 2/3: wiki entities, DM-private notes, notes, read state,
-- calendar, games and per-campaign config.
--
-- Verified locally with `supabase db reset` + `supabase test db` (135+ pgTAP assertions).
--
-- Conventions shared by all entity tables
--   id          bigint generated BY DEFAULT as identity. BY DEFAULT so the Firestore import can
--               keep the existing numeric ids (wiki-links `[[{3G}...]]` depend on them). After an
--               import with explicit ids the import script must advance each sequence:
--                 select setval(pg_get_serial_sequence('public.<table>', 'id'), max(id)) from public.<table>;
--               Ids are unique per TABLE across all campaigns (documented decision: only one Firestore
--               campaign is ever imported with its original ids; any future import must remap ids).
--               Wiki-links resolve within one campaign.
--   campaign_id uuid, tenant key used by every RLS policy.
--   estado      'publicado' | 'secreto' | 'borrador'  (Firestore `estado`, default 'publicado').
--   visible_to  bigint[] of pjs.id allowed to see the row when estado = 'secreto'
--               (Firestore `visibilidad`). Array elements cannot carry an FK; RLS only compares them
--               with the caller's own characters, so stale ids are harmless.
--   created_by / created_at / updated_at  (Firestore createdAt / updatedAt).
--   data jsonb  type-specific fields that are not needed for authorization, FKs, filtering or sorting.
--
-- DM-private fields (`notas`, `secreto`, session `ganchos`) are NOT in these tables because RLS is
-- row-level: any row a player can select would expose them. They live in entity_dm_notes (DM only).

------------------------------------------------------------------------------
-- sesiones  (Firestore `sesiones`; includes `avance` entries, tipo = 'avance')
------------------------------------------------------------------------------
-- Firestore field      -> column / data key
--   id, tipo           -> id, tipo ('sesion' | 'avance')
--   numero             -> numero (null for avance)
--   orden              -> orden (double precision: the UI inserts between neighbours with midpoints)
--   titulo             -> titulo
--   fecha ('' | date)  -> fecha (date, '' becomes null)
--   imagen_url         -> imagen_url
--   resumen            -> data.resumen        (sesion)
--   logros             -> data.logros         (sesion)
--   texto              -> data.texto          (avance)
--   ganchos            -> entity_dm_notes.ganchos   (DM only)
--   notas              -> entity_dm_notes.notas     (DM only; avance)
--   estado/visibilidad -> estado / visible_to

create table public.sesiones (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  tipo        text not null default 'sesion' check (tipo in ('sesion', 'avance')),
  numero      integer,
  orden       double precision not null default 0,
  titulo      text not null default '',
  fecha       date,
  imagen_url  text not null default '',
  estado      text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to  bigint[] not null default '{}',
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index sesiones_campaign_orden_idx on public.sesiones (campaign_id, orden);

------------------------------------------------------------------------------
-- pjs  (Firestore `pjs`, player characters)
------------------------------------------------------------------------------
-- Firestore field        -> column / data key
--   id                   -> id
--   nombre, jugador      -> nombre, jugador (free text: real player name; ownership is owner_id)
--   clase, raza, region  -> clase, raza, region (region = campaigns.regions[].key)
--   nivel                -> nivel
--   imagen_url           -> imagen_url
--   sections_updated     -> sections_updated ({section: ISO timestamp}, drives unread dots)
--   notas                -> entity_dm_notes.notas (DM only)
--   player_password, player_must_change -> DROPPED (replaced by Supabase Auth)
--   magralita            -> data.custom_fields.magralita (campaigns.character_custom_fields)
--   every other key      -> data.<same key>:
--     identity   trasfondo_dnd, alineamiento, experiencia, trasfondo, motivo
--     looks      edad, altura, peso, ojos, piel, pelo, apariencia
--     personality personalidad, ideales, vinculos, defectos
--     mechanics  stat_*, save_*, skill_*, idiomas, prof_*, rasgos_clase, otros_rasgos
--     spells     spell_dc, spell_attack_bonus, spell_ability, spell_slots, spell_slots_current, hechizos[]
--     inventory  ataques[], equipo[], recursos[]
--   monedas, monedas_guardado -> columns monedas / monedas_guardado (jsonb {cp,sp,ep,gp,pp}); kept out of
--     data so coin balances are never overwritten by a whole-data update: the data layer must use
--     PATCH updates (only the changed keys), never whole-row overwrites. DM-writable only; players
--     get coins through play_loteria() / assign_pot_to_character().
--   estado/visibilidad   -> estado / visible_to
-- owner_id is the user who controls the character (null = unclaimed, e.g. right after import).
-- A non-DM owner may edit only the identity subset enforced by guard_pj_player_update() (part 3).

create table public.pjs (
  id               bigint generated by default as identity primary key,
  campaign_id      uuid not null references public.campaigns (id) on delete cascade,
  owner_id         uuid references public.profiles (id) on delete set null,
  nombre           text not null default '',
  jugador          text not null default '',
  clase            text not null default '',
  raza             text not null default '',
  region           text not null default '',
  nivel            integer not null default 1 check (nivel between 1 and 20),
  imagen_url       text not null default '',
  sections_updated jsonb not null default '{}'::jsonb check (jsonb_typeof(sections_updated) = 'object'),
  monedas          jsonb not null default '{"cp":0,"sp":0,"ep":0,"gp":0,"pp":0}'::jsonb check (jsonb_typeof(monedas) = 'object'),
  monedas_guardado jsonb not null default '{}'::jsonb check (jsonb_typeof(monedas_guardado) = 'object'),
  estado           text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to       bigint[] not null default '{}',
  data             jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by       uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  -- target of composite FKs that keep child rows inside the same campaign
  unique (id, campaign_id)
);
create index pjs_campaign_id_idx on public.pjs (campaign_id);
create index pjs_campaign_owner_idx on public.pjs (campaign_id, owner_id) where owner_id is not null;

-- deferred from part 1: invites may reference the character they hand over
alter table public.campaign_invites
  add constraint campaign_invites_character_fk
  foreign key (character_id, campaign_id) references public.pjs (id, campaign_id) on delete cascade;

------------------------------------------------------------------------------
-- pnjs  (Firestore `pnjs`)
------------------------------------------------------------------------------
--   nombre, region, relacion, imagen_url -> columns (relacion: aliado|neutral|enemigo|desconocido)
--   rol, faccion (free-text name), descripcion, historia -> data.<same key>
--   secreto, notas -> entity_dm_notes (DM only)

create table public.pnjs (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  nombre      text not null default '',
  region      text not null default '',
  relacion    text not null default 'neutral',
  imagen_url  text not null default '',
  estado      text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to  bigint[] not null default '{}',
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index pnjs_campaign_id_idx on public.pnjs (campaign_id);

------------------------------------------------------------------------------
-- lugares  (Firestore `lugares`)
------------------------------------------------------------------------------
--   nombre, region, tipo, imagen_url -> columns
--   subtitulo, descripcion -> data.<same key>
--   notas -> entity_dm_notes.notas (DM only)

create table public.lugares (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  nombre      text not null default '',
  region      text not null default '',
  tipo        text not null default 'ciudad',
  imagen_url  text not null default '',
  estado      text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to  bigint[] not null default '{}',
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index lugares_campaign_id_idx on public.lugares (campaign_id);

------------------------------------------------------------------------------
-- facciones  (Firestore `facciones`)
------------------------------------------------------------------------------
--   nombre, tipo, region, relacion, imagen_url -> columns
--   descripcion -> data.descripcion
--   secreto, notas -> entity_dm_notes (DM only)

create table public.facciones (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  nombre      text not null default '',
  tipo        text not null default 'facción',
  region      text not null default '',
  relacion    text not null default 'neutral',
  imagen_url  text not null default '',
  estado      text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to  bigint[] not null default '{}',
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index facciones_campaign_id_idx on public.facciones (campaign_id);

------------------------------------------------------------------------------
-- lore  (Firestore `lore`)
------------------------------------------------------------------------------
--   titulo, categoria (lower-cased by the form) -> columns
--   descripcion -> data.descripcion
--   notas ("información secreta, solo DM") -> entity_dm_notes.notas (DM only)

create table public.lore (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  titulo      text not null default '',
  categoria   text not null default '',
  estado      text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to  bigint[] not null default '{}',
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index lore_campaign_id_idx on public.lore (campaign_id);

------------------------------------------------------------------------------
-- items  (Firestore `items`)
------------------------------------------------------------------------------
--   nombre, tipo, rareza, imagen_url -> columns
--   requiere_sintonia, descripcion, lore, poseedor -> data.<same key>
--   (items have no DM-private fields in the current UI)

create table public.items (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  nombre      text not null default '',
  tipo        text not null default 'objeto maravilloso',
  rareza      text not null default 'raro',
  imagen_url  text not null default '',
  estado      text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to  bigint[] not null default '{}',
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index items_campaign_id_idx on public.items (campaign_id);

------------------------------------------------------------------------------
-- mapas  (Firestore `mapas`)
------------------------------------------------------------------------------
--   nombre, imagen_url, is_default -> columns (one default map per campaign, partial unique index)
--   descripcion -> data.descripcion
--   notas -> entity_dm_notes.notas (DM only)

create table public.mapas (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  nombre      text not null default '',
  imagen_url  text not null default '',
  is_default  boolean not null default false,
  estado      text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to  bigint[] not null default '{}',
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (id, campaign_id)
);
create index mapas_campaign_id_idx on public.mapas (campaign_id);
create unique index mapas_one_default_per_campaign on public.mapas (campaign_id) where is_default;

------------------------------------------------------------------------------
-- map_points  (Firestore `map_points`)
------------------------------------------------------------------------------
--   map_id -> map_id (FK, composite with campaign_id so a point cannot point at another campaign's map)
--   nombre -> nombre; x, y -> x, y (normalised 0..1); link_type, link_id -> same
--   descripcion -> data.descripcion
-- link_id is polymorphic (depends on link_type) so it cannot be an FK. Valid link_type values mirror
-- wikiHelpers COLLECTION_LETTER; the old 'mapa' link targets mapas.

create table public.map_points (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  map_id      bigint not null,
  nombre      text not null default '',
  x           double precision not null default 0.5 check (x between 0 and 1),
  y           double precision not null default 0.5 check (y between 0 and 1),
  link_type   text check (link_type in ('lugar', 'pnj', 'faccion', 'lore', 'item', 'sesion', 'mapa')),
  link_id     bigint,
  estado      text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to  bigint[] not null default '{}',
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint map_points_map_fk foreign key (map_id, campaign_id)
    references public.mapas (id, campaign_id) on delete cascade,
  check ((link_type is null) = (link_id is null))
);
create index map_points_campaign_id_idx on public.map_points (campaign_id);
create index map_points_map_id_idx on public.map_points (map_id);

------------------------------------------------------------------------------
-- homebrew_rules  (Firestore `homebrew_rules`: { id, nombre, texto, estado, visibilidad })
------------------------------------------------------------------------------

create table public.homebrew_rules (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  nombre      text not null default '',
  texto       text not null default '',
  estado      text not null default 'publicado' check (estado in ('publicado', 'secreto', 'borrador')),
  visible_to  bigint[] not null default '{}',
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index homebrew_rules_campaign_id_idx on public.homebrew_rules (campaign_id);

------------------------------------------------------------------------------
-- entity_dm_notes: DM-only private fields of entities
------------------------------------------------------------------------------
-- One row per entity: notas / secreto / ganchos (blank when unused). entity_type is the table name.
-- Not an FK (polymorphic); validated by trigger in part 3 and cleaned up when the entity is deleted.
-- Which fields exist per type (from the current forms):
--   pnjs: secreto, notas      facciones: secreto, notas    lugares: notas   lore: notas
--   pjs: notas                mapas: notas                 sesiones: ganchos, notas (avance)

create table public.entity_dm_notes (
  id          bigint generated by default as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  entity_type text not null check (entity_type in
                ('sesiones', 'pjs', 'pnjs', 'lugares', 'facciones', 'lore', 'items', 'mapas')),
  entity_id   bigint not null,
  notas       text not null default '',
  secreto     text not null default '',
  ganchos     text not null default '',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (entity_type, entity_id)
);
create index entity_dm_notes_campaign_id_idx on public.entity_dm_notes (campaign_id);

------------------------------------------------------------------------------
-- player_notes (Firestore `player_notes`, id `${pj_id}_${type}_${entity_id}`)
------------------------------------------------------------------------------
-- Owned by the user, not by the PJ id: a user writes notes as themselves in each campaign.
-- character_id is informational (the PJ shown to the DM next to the note).

create table public.player_notes (
  campaign_id  uuid not null references public.campaigns (id) on delete cascade,
  user_id      uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  entity_type  text not null check (entity_type in
                 ('sesiones', 'pjs', 'pnjs', 'lugares', 'facciones', 'lore', 'items')),
  entity_id    bigint not null,
  character_id bigint,
  text         text not null default '',
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  primary key (user_id, campaign_id, entity_type, entity_id),
  constraint player_notes_character_fk foreign key (character_id, campaign_id)
    references public.pjs (id, campaign_id) on delete set null (character_id)
);
create index player_notes_campaign_entity_idx on public.player_notes (campaign_id, entity_type, entity_id);

------------------------------------------------------------------------------
-- read_state (Firestore `read_state`, id `${viewerId}_${type}_${entityId}[_section]`)
------------------------------------------------------------------------------
-- Per user + campaign + entity. `section` is '' for whole entities and a PJ section key
-- ('stats', 'equipo', ...) for per-section unread tracking on pjs. The DM is no longer the
-- shared viewer 'dm': it is just another user.

create table public.read_state (
  user_id     uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  entity_type text not null check (entity_type in
                ('sesiones', 'pjs', 'pnjs', 'lugares', 'facciones', 'lore', 'items')),
  entity_id   bigint not null,
  section     text not null default '',
  seen_at     timestamptz not null default now(),
  primary key (user_id, campaign_id, entity_type, entity_id, section)
);
create index read_state_campaign_id_idx on public.read_state (campaign_id);

------------------------------------------------------------------------------
-- disponibilidad (Firestore `disponibilidad`)
------------------------------------------------------------------------------
-- tipo 'sesion'        DM-created session slot: fecha_inicio/fin + hora_inicio/fin, no character.
-- tipo 'personal'      a player's availability window (same four fields) for one of their characters.
-- tipo 'no_disponible' whole-day "not available" mark: `fecha` only.
-- pj_id -> character_id. Everyone in the campaign sees the calendar (the UI shows all PJs).

create table public.disponibilidad (
  id           bigint generated by default as identity primary key,
  campaign_id  uuid not null references public.campaigns (id) on delete cascade,
  tipo         text not null check (tipo in ('sesion', 'personal', 'no_disponible')),
  character_id bigint,
  fecha        date,
  fecha_inicio date,
  fecha_fin    date,
  hora_inicio  time,
  hora_fin     time,
  created_by   uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  constraint disponibilidad_character_fk foreign key (character_id, campaign_id)
    references public.pjs (id, campaign_id) on delete cascade,
  check ((tipo = 'sesion') = (character_id is null)),
  check (tipo <> 'no_disponible' or fecha is not null),
  check (tipo = 'no_disponible'
         or (fecha_inicio is not null and fecha_fin is not null
             and hora_inicio is not null and hora_fin is not null
             and fecha_fin >= fecha_inicio))
);
create index disponibilidad_campaign_id_idx on public.disponibilidad (campaign_id);
create index disponibilidad_character_id_idx on public.disponibilidad (character_id);

------------------------------------------------------------------------------
-- Games: game_logs, game_pot, and config
------------------------------------------------------------------------------
-- game_logs  Firestore `game_logs` (id `${pjId}_loteria_${date}` | `dm_loteria_${ts}`).
--   playerId -> character_id, actorType -> actor_type, date -> play_date (UTC), prizeTarget -> prize_target.
--   One lottery play per character per UTC day is enforced by a partial unique index (it replaces the
--   deterministic Firestore doc id). Rows are written only by play_loteria() (part 3).

create table public.game_logs (
  id           bigint generated by default as identity primary key,
  campaign_id  uuid not null references public.campaigns (id) on delete cascade,
  actor_type   text not null check (actor_type in ('player', 'dm')),
  character_id bigint,
  game         text not null default 'loteria',
  play_date    date not null default ((now() at time zone 'utc')::date),
  roll         smallint not null check (roll between 1 and 20),
  prize        jsonb not null default '{}'::jsonb check (jsonb_typeof(prize) = 'object'),
  prize_target text not null check (prize_target in ('player', 'pot')),
  created_at   timestamptz not null default now(),
  constraint game_logs_character_fk foreign key (character_id, campaign_id)
    references public.pjs (id, campaign_id) on delete set null (character_id),
  check ((actor_type = 'player') = (prize_target = 'player'))
);
create index game_logs_campaign_id_idx on public.game_logs (campaign_id, created_at desc);
create unique index game_logs_one_play_per_day
  on public.game_logs (campaign_id, character_id, game, play_date)
  where actor_type = 'player' and character_id is not null;

-- game_pot  Firestore `game_pot/current`: the DM's shared coin pot, one row per campaign.
create table public.game_pot (
  campaign_id uuid primary key references public.campaigns (id) on delete cascade,
  cp          bigint not null default 0 check (cp >= 0),
  sp          bigint not null default 0 check (sp >= 0),
  ep          bigint not null default 0 check (ep >= 0),
  gp          bigint not null default 0 check (gp >= 0),
  pp          bigint not null default 0 check (pp >= 0),
  updated_at  timestamptz not null default now()
);

-- campaign_config  Firestore `game_config/*`.
-- DECISION: a (campaign_id, key) table rather than columns in campaigns.settings because
--   1. the session screen layout (card order, combat tracker, DM notes) is written on every drag/edit
--      and can be large; keeping it out of the campaigns row avoids rewriting and shipping it with
--      every campaigns select (campaigns is read by every member, on every page load);
--   2. RLS differs per key: `loteria` is readable by members, `session_screen` is DM-only (the
--      `visibility` column drives it), which one jsonb column on campaigns could not express;
--   3. keys can be patched independently (no read-modify-write of unrelated settings).
-- Keys in use: 'loteria'        value {commonMinRoll, commonPrize{cp..pp}, specialPrize{cp..pp}}
--              'session_screen' value {cards: [...]}   (DM only)

create table public.campaign_config (
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  key         text not null check (char_length(key) between 1 and 64),
  value       jsonb not null default '{}'::jsonb,
  visibility  text not null default 'members' check (visibility in ('members', 'dm')),
  updated_at  timestamptz not null default now(),
  primary key (campaign_id, key)
);

------------------------------------------------------------------------------
-- Triggers: updated_at and campaign_id immutability
------------------------------------------------------------------------------

do $$
declare
  t text;
begin
  foreach t in array array[
    'sesiones', 'pjs', 'pnjs', 'lugares', 'facciones', 'lore', 'items', 'mapas', 'map_points',
    'homebrew_rules', 'entity_dm_notes', 'player_notes', 'disponibilidad', 'game_pot', 'campaign_config'
  ] loop
    execute format(
      'create trigger %I before update on public.%I for each row execute function public.set_updated_at()',
      t || '_set_updated_at', t);
  end loop;

  foreach t in array array[
    'sesiones', 'pjs', 'pnjs', 'lugares', 'facciones', 'lore', 'items', 'mapas', 'map_points',
    'homebrew_rules', 'entity_dm_notes', 'player_notes', 'read_state', 'disponibilidad', 'game_logs',
    'game_pot', 'campaign_config', 'campaign_invites', 'campaign_members'
  ] loop
    execute format(
      'create trigger %I before update on public.%I for each row execute function public.forbid_campaign_id_change()',
      t || '_forbid_campaign_change', t);
  end loop;
end;
$$;

-- When an entity is deleted, drop the rows that point at it polymorphically.
create function public.cleanup_entity_children()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.entity_dm_notes where entity_type = tg_argv[0] and entity_id = old.id;
  delete from public.player_notes where entity_type = tg_argv[0] and entity_id = old.id;
  delete from public.read_state where entity_type = tg_argv[0] and entity_id = old.id;
  return old;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array['sesiones', 'pjs', 'pnjs', 'lugares', 'facciones', 'lore', 'items', 'mapas'] loop
    execute format(
      'create trigger %I after delete on public.%I for each row execute function public.cleanup_entity_children(%L)',
      t || '_cleanup_children', t, t);
  end loop;
end;
$$;

-- id and created_by are write-once for API callers: a DM could otherwise rewrite them with a plain
-- UPDATE (forging authorship, or renumbering ids that wiki-links and notes point to).
-- Table-owner / service_role writes (FK actions such as `on delete set null`, the import script)
-- are exempt; everyone else is checked.
create function public.forbid_identity_change()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user in ('postgres', 'supabase_admin', 'service_role') then
    return new;
  end if;
  if new.id is distinct from old.id or new.created_by is distinct from old.created_by then
    raise exception 'id and created_by are immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'sesiones', 'pjs', 'pnjs', 'lugares', 'facciones', 'lore', 'items', 'mapas', 'map_points',
    'homebrew_rules', 'disponibilidad'
  ] loop
    execute format(
      'create trigger %I before update on public.%I for each row execute function public.forbid_identity_change()',
      t || '_forbid_identity_change', t);
  end loop;
end;
$$;
